using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Loads an asynchronous or a zoomed in statistical graph
    /// </summary>
    public Task<TdLib.TdApi.Objects.StatisticalGraph> GetStatisticalGraphAsync(long chatId = default, string token = default, long x = default)
    {

           using var activity =  StartCallActivity("GetStatisticalGraphAsync", typeof(GetStatisticalGraph).FullName ?? "GetStatisticalGraphAsync");

           try
           {
             return client.GetStatisticalGraphAsync(chatId, token, x);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
